var e=[{id:1,text:'¿Qué característica definía primordialmente la pedagogía en las "casas de tablillas" o edubba en la civilización mesopotámica?',sorted:!1,options:[{text:"La promoción del pensamiento crítico y la innovación teórica sobre los textos antiguos.",correct:!1},{text:"La aplicación de un sistema inclusivo que permitía el acceso a mujeres de la élite administrativa.",correct:!1},{text:"Una disciplina rigurosa basada en el castigo físico para asegurar la precisión caligráfica y administrativa.",correct:!0},{text:"Un enfoque puramente humanista centrado en el desarrollo de la areté o excelencia personal.",correct:!1}]},{id:2,text:'En el contexto del antiguo Egipto, ¿cuál era la distinción funcional entre la formación sacerdotal y la funcionarial dentro de la "Casa de la Vida"?',sorted:!1,options:[{text:"La sacerdotal se centraba en la geometría práctica de los agrimensores, mientras la funcionarial en la astronomía.",correct:!1},{text:"La sacerdotal enseñaba jeroglíficos y teología, mientras la funcionarial dominaba la escritura hierática y la administración.",correct:!0},{text:"Ambas ramas utilizaban exclusivamente el jeroglífico monumental para la documentación cotidiana.",correct:!1},{text:"La formación funcionarial estaba reservada a los esclavos cultos, mientras que la sacerdotal a los hijos del faraón.",correct:!1}]},{id:3,text:"Dentro del modelo de la paideia ateniense, ¿cuál era la función principal del pedagogo?",sorted:!1,options:[{text:"Ser el maestro titular de retórica en la escuela superior para jóvenes de catorce años.",correct:!1},{text:"Un esclavo encargado de guiar y conducir al niño a la escuela, supervisando su conducta y valores.",correct:!0},{text:"Instruir a las madres y nodrizas en el arte de la recitación de los mitos homéricos.",correct:!1},{text:"Organizar las competiciones de gimnasia en la palestra para los juegos olímpicos.",correct:!1}]},{id:4,text:"A diferencia de los Sofistas, ¿cuál era el objetivo fundamental del método de la mayéutica desarrollado por Sócrates?",sorted:!1,options:[{text:"Adiestrar al alumno en la persuasión para obtener éxito en la Asamblea y tribunales.",correct:!1},{text:"Ayudar al interlocutor a descubrir por sí mismo conocimientos latentes mediante el diálogo.",correct:!0},{text:"Sistematizar un currículo basado exclusivamente en las matemáticas y la armonía musical.",correct:!1},{text:"Cobrar honorarios elevados por enseñar técnicas de argumentación lógica infalibles.",correct:!1}]},{id:5,text:"Según el pensamiento de Aristóteles, la educación debía ser un proceso holístico sustentado en tres pilares fundamentales. ¿Cuáles son?",sorted:!1,options:[{text:"Naturaleza, Hábito y Razón.",correct:!0},{text:"Retórica, Dialéctica y Gramática.",correct:!1},{text:"Gimnasia, Música y Aritmética.",correct:!1},{text:"Supervivencia, Astucia y Disciplina militar.",correct:!1}]},{id:6,text:"En la civilización espartana, ¿cuál era el propósito de la educación física exigente que recibían las mujeres?",sorted:!1,options:[{text:"Prepararlas para participar como combatientes activas en las legiones de hoplitas.",correct:!1},{text:"Fomentar el desarrollo armónico del alma y la apreciación estética de la gimnasia.",correct:!1},{text:"Asegurar que fueran madres fuertes capaces de engendrar descendencia sana y vigorosa para el Estado.",correct:!0},{text:"Capacitarlas para el debate político en la Asamblea de ciudadanos libres.",correct:!1}]},{id:7,text:"Durante la etapa de la República romana, ¿cómo se transformó el carácter originalmente doméstico de la educación?",sorted:!1,options:[{text:"Se prohibió la instrucción del pater familias para centralizarla en escuelas estatales.",correct:!1},{text:"Se adoptaron elementos del modelo griego mediante el uso de esclavos cultos como tutores.",correct:!0},{text:"Se eliminó el pragmatismo para adoptar una visión puramente contemplativa del saber.",correct:!1},{text:"Se priorizó el bilingüismo en etrusco y latín para mantener las tradiciones agrícolas.",correct:!1}]},{id:8,text:"En el sistema educativo del Imperio Romano, ¿qué se enseñaba específicamente en la escuela del rhetor?",sorted:!1,options:[{text:"Lectura, escritura y aritmética básica bajo la supervisión del ludi magister.",correct:!1},{text:"El estudio de los autores clásicos como Virgilio y Cicerón bajo la guía del grammaticus.",correct:!1},{text:"Especialización en oratoria, derecho y filosofía para aspirantes a la carrera pública.",correct:!0},{text:"Técnicas de combate y gladiación para prisioneros de guerra y hombres libres.",correct:!1}]},{id:9,text:'En la Alta Edad Media, ¿cuál era la distinción entre la "schola interior" y la "schola exterior" dentro de los monasterios?',sorted:!1,options:[{text:"La interior era para el estudio de ciencias y la exterior para el estudio de letras.",correct:!1},{text:"La interior formaba a futuros monjes y la exterior a clérigos seculares o sacerdotes.",correct:!0},{text:"La interior estaba ubicada en las ciudades y la exterior en zonas rurales aisladas.",correct:!1},{text:"La interior era para nobles y la exterior para siervos de la gleba.",correct:!1}]},{id:10,text:"El currículo medieval se dividía en Trivium y Quadrivium. ¿Qué disciplinas componían el Quadrivium?",sorted:!1,options:[{text:"Gramática, Dialéctica y Retórica.",correct:!1},{text:"Aritmética, Geometría, Astronomía y Música.",correct:!0},{text:"Teología, Derecho Canónico, Medicina y Filosofía.",correct:!1},{text:"Esgrima, Equitación, Caza y Poesía.",correct:!1}]},{id:11,text:"¿Cuál fue la aportación educativa más relevante de las madrasas islámicas a la Europa medieval?",sorted:!1,options:[{text:"La invención de la imprenta para multiplicar los ejemplares del Corán.",correct:!1},{text:"La imposición del bilingüismo en árabe y latín en todos los monasterios cristianos.",correct:!1},{text:"La introducción del método dialéctico y el modelo residencial que influyó en los colegios universitarios.",correct:!0},{text:"La eliminación de los estudios clásicos griegos para centrarse solo en la teología.",correct:!1}]},{id:12,text:"En el contexto de la Baja Edad Media, ¿qué diferencia principal existía entre los modelos organizativos de las universidades de Bolonia y París?",sorted:!1,options:[{text:"En Bolonia los estudiantes tenían autonomía para contratar profesores, mientras en París el poder residía en los docentes.",correct:!0},{text:"Bolonia se especializaba exclusivamente en Medicina y París en Derecho Canónico.",correct:!1},{text:"En París los exámenes eran privados, mientras en Bolonia eran espectáculos públicos con banquetes.",correct:!1},{text:"Bolonia prohibía la escolástica y París la fomentaba como método único.",correct:!1}]},{id:13,text:"Durante el Renacimiento, ¿cómo se redefinió el objetivo de la educación bajo la influencia del Humanismo?",sorted:!1,options:[{text:"Se limitó la educación a la formación técnica de oficiales y maestros de los gremios.",correct:!1},{text:"Se buscó la formación de ciudadanos críticos y cultos mediante el contacto directo con los textos grecolatinos.",correct:!0},{text:"Se priorizó la visión teocéntrica medieval para evitar el avance del pensamiento científico.",correct:!1},{text:"Se prohibió el estudio de las lenguas vernáculas para centrarse exclusivamente en el latín eclesiástico.",correct:!1}]},{id:14,text:"¿Cuál fue la principal motivación de Martín Lutero para defender la alfabetización universal durante la Reforma protestante?",sorted:!1,options:[{text:"Preparar a la población para las nuevas exigencias de la industria textil.",correct:!1},{text:"Garantizar que todos los fieles pudieran acceder y leer directamente las Sagradas Escrituras.",correct:!0},{text:"Promover el bilingüismo en alemán y latín para mejorar las relaciones diplomáticas.",correct:!1},{text:"Fomentar la creación de universidades jesuitas en territorios protestantes.",correct:!1}]},{id:15,text:"En el siglo XVIII, el Estado prusiano marcó un hito histórico en la educación. ¿Cuál fue su principal innovación legislativa?",sorted:!1,options:[{text:"La prohibición de la educación femenina en todas las escuelas de los pueblos.",correct:!1},{text:"El establecimiento de la educación obligatoria para niños y niñas de entre 5 y 14 años.",correct:!0},{text:"La entrega total de la gestión educativa a las órdenes religiosas católicas.",correct:!1},{text:"La eliminación de las matemáticas del currículo para centrarse solo en la formación militar.",correct:!1}]},{id:16,text:'Etimológicamente, el término educación proviene de "educare" y "educere". ¿Qué concepto se asocia específicamente con "educere"?',sorted:!1,options:[{text:"La idea de alimentar, nutrir y criar al individuo desde el exterior.",correct:!1},{text:"El proceso de sacar fuera o desarrollar las potencialidades innatas del sujeto.",correct:!0},{text:"La imposición de normas y valores para la cohesión social inmediata.",correct:!1},{text:"El esfuerzo y la aplicación perseverante del estudiante durante el estudio.",correct:!1}]},{id:17,text:"Desde la perspectiva de la sociología de la educación, ¿cómo definió Émile Durkheim el fenómeno educativo?",sorted:!1,options:[{text:"Como un proceso de emancipación intelectual individual e independiente de la sociedad.",correct:!1},{text:"Como una construcción social donde las generaciones adultas transmiten normas y valores para asegurar la cohesión.",correct:!0},{text:"Como un diálogo horizontal e igualitario donde no existe jerarquía entre maestro y alumno.",correct:!1},{text:'Como un método de "banca" donde se depositan conocimientos de forma pasiva.',correct:!1}]},{id:18,text:'¿Cuál es la premisa fundamental de la "Pedagogía de la autonomía" de Paulo Freire?',sorted:!1,options:[{text:"La superioridad absoluta del maestro como poseedor único de la verdad científica.",correct:!1},{text:"El rechazo a la educación formal en favor de un aprendizaje puramente instintivo.",correct:!1},{text:"La construcción conjunta del conocimiento mediante un diálogo horizontal entre educador y educando.",correct:!0},{text:"La formación técnica exclusiva para la inserción en el mercado laboral globalizado.",correct:!1}]},{id:19,text:'El Informe Delors (1996) propone "cuatro pilares de la educación". ¿A qué hace referencia el pilar de "Aprender a hacer"?',sorted:!1,options:[{text:"Al desarrollo del juicio propio y la autonomía de pensamiento.",correct:!1},{text:"A la adquisición de competencias prácticas, trabajo colaborativo y resolución de problemas.",correct:!0},{text:"Al descubrimiento del otro y la participación en proyectos comunes.",correct:!1},{text:"Al dominio de los instrumentos del conocimiento para comprender el mundo.",correct:!1}]},{id:20,text:'En el contexto de la dimensión social de la educación, ¿qué se entiende por "contrato social educativo"?',sorted:!1,options:[{text:"Un acuerdo legal firmado obligatoriamente por cada alumno al matricularse.",correct:!1},{text:"Un pacto entre empresas tecnológicas y escuelas para la venta de dispositivos digitales.",correct:!1},{text:"El acuerdo explícito o implícito sobre los fines, valores y responsabilidades de la educación en una sociedad.",correct:!0},{text:"La regulación que prohíbe la participación de la familia en las decisiones escolares.",correct:!1}]},{id:21,text:"¿Cómo influyó la invención de la imprenta de Gutenberg en la metodología pedagógica de la Edad Moderna?",sorted:!1,options:[{text:"Hizo que la educación fuera exclusivamente oral para evitar el desgaste de los libros.",correct:!1},{text:"Permitió el acceso masivo a libros de texto, favoreciendo un aprendizaje más autónomo y reflexivo.",correct:!0},{text:"Eliminó la necesidad de maestros, ya que los libros se explicaban por sí solos.",correct:!1},{text:"Restringió el conocimiento a las bibliotecas de los monasterios más alejados.",correct:!1}]},{id:22,text:"En la civilización fenicia, ¿cuál era la orientación primordial de su sistema educativo?",sorted:!1,options:[{text:"La formación teológica profunda para la preservación de rituales funerarios complejos.",correct:!1},{text:"Una clara vocación profesional y práctica orientada a la navegación y el comercio.",correct:!0},{text:"El desarrollo de la democracia participativa a través de la retórica.",correct:!1},{text:"La exclusión total del sistema de escritura para mantener los secretos comerciales en secreto.",correct:!1}]},{id:23,text:"¿cuál es el riesgo principal identificado por Durkheim en la función socializadora de la educación?",sorted:!1,options:[{text:"La excesiva libertad de pensamiento que puede llevar a la anarquía.",correct:!1},{text:"La posibilidad de que el maestro no tenga suficiente autoridad sobre los alumnos.",correct:!1},{text:"El peligro de la homogeneización y la perpetuación de desigualdades preexistentes.",correct:!0},{text:"La falta de contenidos técnicos útiles para la economía industrial.",correct:!1}]},{id:24,text:"¿Qué función cumple el grupo de iguales (compañeros y amigos) como agente de socialización según la dimensión social de la educación?",sorted:!1,options:[{text:"Sustituir por completo a la familia en la formación de la lengua materna.",correct:!1},{text:"Favorecer la autonomía y la construcción de la identidad personal y generacional.",correct:!0},{text:"Garantizar la financiación pública del sistema educativo nacional.",correct:!1},{text:"Imponer de forma institucionalizada los conocimientos científicos sistematizados.",correct:!1}]},{id:25,text:"En la Roma antigua, ¿cuál era la finalidad de los ejercicios físicos realizados en el Campo de Marte?",sorted:!1,options:[{text:"El desarrollo armónico del cuerpo para la apreciación estética y artística.",correct:!1},{text:"La preparación estricta para la guerra y el servicio militar.",correct:!0},{text:"La formación en danzas corales para las festividades religiosas anuales.",correct:!1},{text:"Proporcionar un espacio de ocio y recreación para los esclavos liberados.",correct:!1}]},{id:26,text:'Dentro de la evolución de la educación contemporánea, ¿qué defiende el concepto de "aprendizaje dialógico"?',sorted:!1,options:[{text:"Que el aprendizaje es un proceso puramente individual que ocurre sin interacción social.",correct:!1},{text:"La prioridad de la inteligencia emocional sobre los conocimientos lógicos.",correct:!1},{text:"La interacción igualitaria y la construcción colectiva de significados para la transformación comunitaria.",correct:!0},{text:"La obligatoriedad de utilizar medios digitales como única vía de comunicación pedagógica.",correct:!1}]}],a=[{id:1,text:"¿Cómo se define la relación dialéctica entre los procesos de socialización formal e informal?",sorted:!1,options:[{text:"Como una interacción dinámica donde las bases informales y los sistemas estructurados se retroalimentan y transforman mutuamente.",correct:!0},{text:"Como una subordinación necesaria de los rituales familiares ante los currículos académicos estatales.",correct:!1},{text:"Como la separación estricta entre el aprendizaje de valores cívicos y la internalización de roles de género.",correct:!1},{text:"Como un proceso unidireccional donde las instituciones formales dictan la evolución de las prácticas cotidianas.",correct:!1}]},{id:2,text:"Según la teoría de Bronfenbrenner, ¿cuál es la función principal del mesosistema en el desarrollo del individuo?",sorted:!1,options:[{text:"Establecer las interrelaciones y vínculos entre los distintos microsistemas en los que participa la persona.",correct:!0},{text:"Dictar las leyes y marcos culturales globales que rigen el comportamiento social.",correct:!1},{text:"Gestionar los entornos en los que el individuo no participa pero que le afectan indirectamente, como el trabajo de los padres.",correct:!1},{text:"Regular las transiciones históricas y vitales que ocurren a lo largo del tiempo.",correct:!1}]},{id:3,text:"¿Qué crítica fundamental realizó David Schneider a las definiciones clásicas de familia y parentesco?",sorted:!1,options:[{text:"Argumentó que estaban sesgadas por una visión androcéntrica y etnocéntrica que asumía la biología como base universal.",correct:!0},{text:"Sostuvo que la familia nuclear es la única estructura capaz de garantizar la estabilidad emocional en sociedades industriales.",correct:!1},{text:"Afirmó que el tabú del incesto es la única regla biológica que determina la organización social de todos los clanes.",correct:!1},{text:"Propuso que los lazos de consanguinidad son más fuertes que las afinidades electivas en contextos urbanos.",correct:!1}]},{id:4,text:'En el contexto de la evolución demográfica española, ¿qué caracteriza a la "etapa demográfica primitiva"?',sorted:!1,options:[{text:"Un crecimiento poblacional lento marcado por altas tasas de natalidad y mortalidad en una economía agraria.",correct:!0},{text:"Un descenso brusco de la mortalidad gracias a la Revolución Industrial pero con natalidad estancada.",correct:!1},{text:"El predominio de hogares unipersonales debido a las migraciones masivas hacia América en el siglo XVI.",correct:!1},{text:"Una esperanza de vida elevada compensada por crisis de subsistencia recurrentes.",correct:!1}]},{id:5,text:"¿Cuál es la principal diferencia funcional entre la poliginia y la poliandria?",sorted:!1,options:[{text:"La poliginia suele vincularse a la acumulación de riqueza, mientras que la poliandria es una respuesta funcional a la escasez de recursos.",correct:!0},{text:"La poliginia es exclusiva de sociedades urbanas y la poliandria de entornos nómadas.",correct:!1},{text:"La poliandria garantiza una mayor tasa de natalidad en comparación con la poliginia.",correct:!1},{text:"La poliginia se basa en la autoridad femenina y la poliandria en la estructura patriarcal.",correct:!1}]},{id:6,text:"Según el informe de la Fundación FOESSA (2019), ¿cuál es el factor determinante en la transmisión intergeneracional de la pobreza en España?",sorted:!1,options:[{text:"La presencia de menores en el hogar, lo que hace a las familias más sensibles a padecer situaciones de exclusión crónica.",correct:!0},{text:"La falta de acceso a tecnologías digitales en las zonas rurales del interior peninsular.",correct:!1},{text:"El rechazo cultural de las familias migrantes a los sistemas de becas públicas.",correct:!1},{text:"La excesiva movilidad geográfica de los jóvenes profesionales en busca de empleo.",correct:!1}]},{id:7,text:'¿Qué innovación introduce la nueva Ley de Familias de España respecto al concepto tradicional de "familia numerosa"?',sorted:!1,options:[{text:'Elimina el término y lo sustituye por "familias con mayores necesidades de apoyo a la crianza", ampliando los supuestos de protección.',correct:!0},{text:"Restringe los beneficios fiscales únicamente a aquellas familias con cuatro o más hijos biológicos.",correct:!1},{text:"Establece que solo las familias nucleares con bajos ingresos pueden acceder al título oficial.",correct:!1},{text:"Obliga a las parejas de hecho a contraer matrimonio para recibir ayudas a la natalidad.",correct:!1}]},{id:8,text:'¿A qué se refiere el concepto de "identidades híbridas" en los procesos de socialización de hijos de migrantes?',sorted:!1,options:[{text:"A la negociación entre las prácticas informales de la cultura de origen y las exigencias formales del contexto de acogida.",correct:!0},{text:"A la pérdida total de la lengua materna en favor de una integración lingüística absoluta en la escuela.",correct:!1},{text:"Al uso exclusivo de plataformas digitales para comunicarse con la familia extendida en el país de origen.",correct:!1},{text:"A la resistencia pasiva de los padres a que sus hijos aprendan valores democráticos occidentales.",correct:!1}]},{id:9,text:"En el estudio de Blasi et al. (2011), ¿qué impacto tiene la interacción verbal rica en el desarrollo neurológico infantil?",sorted:!1,options:[{text:"Estimula la corteza prefrontal, área asociada con la empatía y la capacidad de autorregulación emocional.",correct:!0},{text:"Acelera exclusivamente la motricidad fina mediante la imitación de gestos adultos.",correct:!1},{text:"Reduce la necesidad de sueño en los lactantes al aumentar los niveles de dopamina.",correct:!1},{text:"Desarrolla el hemisferio derecho para priorizar el pensamiento lógico-matemático sobre el emocional.",correct:!1}]},{id:10,text:'¿Cómo influyó el "baby boom" (1956-1965) en la estructura familiar española?',sorted:!1,options:[{text:"Consolidó un modelo de familia numerosa vinculado al desarrollo económico antes de la transición hacia el modo de vida urbano e industrial.",correct:!0},{text:"Provocó un descenso inmediato de la nupcialidad debido a la inestabilidad política de la época.",correct:!1},{text:"Marcó el inicio de la incorporación masiva de la mujer al trabajo remunerado fuera del hogar.",correct:!1},{text:"Fue la causa principal del envejecimiento poblacional que observamos en 2024.",correct:!1}]},{id:11,text:"¿Qué representa el microsistema según la teoría ecológica de Bronfenbrenner?",sorted:!1,options:[{text:"El entorno inmediato de interacción directa, cara a cara y bidireccional, como la familia.",correct:!0},{text:"Las instituciones políticas que deciden el currículo escolar nacional.",correct:!1},{text:"La red de amigos de los padres que influyen en el clima emocional del hogar sin conocer al niño.",correct:!1},{text:"Los cambios en la tecnología digital ocurridos durante la última década.",correct:!1}]},{id:12,text:'¿Cuál es la función de los "andamiajes culturales" en el seno de la familia?',sorted:!1,options:[{text:"Proporcionar estructuras de apoyo social y simbólico que guían al niño en la comprensión de las expectativas sociales.",correct:!0},{text:"Garantizar la transmisión íntegra del patrimonio económico al hijo primogénito.",correct:!1},{text:"Sustituir la educación formal de la escuela por enseñanzas místicas o tradicionales.",correct:!1},{text:"Eliminar cualquier conflicto generacional mediante la imposición de una autoridad absoluta.",correct:!1}]},{id:13,text:"Desde la perspectiva feminista de autores como Federici o Butler, ¿cómo se percibe a la familia nuclear?",sorted:!1,options:[{text:"Como una institución social y política que puede reproducir desigualdades de género y la división sexual del trabajo.",correct:!0},{text:"Como la unidad biológica fundamental que garantiza la igualdad natural entre hombres y mujeres.",correct:!1},{text:"Como un espacio de resistencia contra el capitalismo que siempre protege a los más vulnerables.",correct:!1},{text:"Como un modelo obsoleto que ha sido completamente reemplazado por las redes sociales en el siglo XXI.",correct:!1}]},{id:14,text:'¿Qué define a una "familia electiva" según Kath Weston?',sorted:!1,options:[{text:"Redes de parentesco basadas en la afinidad y la elección personal, no necesariamente en la consanguinidad.",correct:!0},{text:"Familias que eligen vivir en el extranjero para maximizar sus ingresos económicos.",correct:!1},{text:"Un modelo donde los hijos eligen a qué progenitor acompañar tras un divorcio.",correct:!1},{text:"Hogares formados exclusivamente por personas que han sido adoptadas legalmente.",correct:!1}]},{id:15,text:'¿Por qué se afirma que la socialización primaria es un proceso "irreversible" emocional y cognitivamente?',sorted:!1,options:[{text:'Porque las estructuras de significado adquiridas en la infancia se experimentan como la "realidad única y natural".',correct:!0},{text:"Porque el cerebro pierde la plasticidad necesaria para aprender nuevos idiomas después de los seis años.",correct:!1},{text:"Porque legalmente los padres no pueden renunciar a la tutela de sus hijos una vez establecida.",correct:!1},{text:"Porque los niños carecen de la capacidad de cuestionar las normas hasta la adolescencia tardía.",correct:!1}]},{id:16,text:"¿Qué factor sociocultural contribuyó significativamente al brusco descenso de la natalidad en España a partir de 1975?",sorted:!1,options:[{text:"La incorporación masiva de la mujer al mercado laboral y el uso generalizado de métodos anticonceptivos.",correct:!0},{text:"La prohibición estatal de tener más de dos hijos para frenar el gasto público.",correct:!1},{text:"Un retorno masivo de la población hacia las zonas rurales tras el baby boom.",correct:!1},{text:"El aumento de la influencia religiosa que promovía el celibato laico.",correct:!1}]},{id:17,text:'En el marco de la diversidad familiar, ¿qué caracteriza a una "familia matrifocal"?',sorted:!1,options:[{text:"La mujer actúa como la figura central de autoridad y sustento, a menudo prescindiendo de la presencia masculina estable.",correct:!0},{text:"Un hogar compuesto exclusivamente por una madre y sus hijas varones.",correct:!1},{text:"La obligación legal de que las hijas hereden la propiedad antes que los hijos varones.",correct:!1},{text:"Familias donde el padre asume las tareas domésticas mientras la madre trabaja fuera.",correct:!1}]},{id:18,text:'¿Cuál es la principal característica de la "familia troncal" dentro de los modelos extensos?',sorted:!1,options:[{text:"Una sola línea de descendencia permanece en la casa ancestral mientras el resto de los hijos se emancipa o queda subordinado.",correct:!0},{text:"Todos los hijos tienen la obligación de vivir en la misma casa con sus cónyuges indefinidamente.",correct:!1},{text:"Es un modelo donde los abuelos no tienen voz en la crianza de los nietos.",correct:!1},{text:"Se basa en la rotación de los hijos por diferentes hogares cada cinco años.",correct:!1}]},{id:19,text:"¿qué impacto tiene la digitalización en la distinción tradicional entre agentes socializadores primarios y secundarios?",sorted:!1,options:[{text:"Desdibuja los límites, ya que agentes tradicionalmente secundarios (como redes sociales) intervienen ahora en la socialización primaria.",correct:!0},{text:"Refuerza la autoridad de la familia al permitirle controlar todo el contenido que consumen los menores.",correct:!1},{text:"Elimina la necesidad de la escuela como agente socializador secundario.",correct:!1},{text:"Asegura que los procesos informales sean ahora totalmente estructurados y evaluables.",correct:!1}]},{id:20,text:"¿Qué implicación tiene el artículo 12 de la Convención sobre los Derechos del Niño (1989) en el ámbito educativo?",sorted:!1,options:[{text:"Reconoce el derecho de los menores a ser escuchados y a que sus opiniones sean tenidas en cuenta en los asuntos que les afectan.",correct:!0},{text:"Establece que los niños deben participar en la votación de las leyes nacionales a partir de los diez años.",correct:!1},{text:"Obliga a los padres a consultar con un juez antes de imponer cualquier castigo disciplinario en el hogar.",correct:!1},{text:"Determina que el currículo escolar debe ser diseñado íntegramente por los propios estudiantes mediante asambleas.",correct:!1}]},{id:21,text:"En la teoría de Lévi-Strauss, ¿cuál es el propósito social de la exogamia?",sorted:!1,options:[{text:"Garantizar la cohesión y supervivencia del grupo mediante la creación de redes de alianza y cooperación con otros grupos.",correct:!0},{text:"Evitar mutaciones genéticas negativas derivadas de la endogamia excesiva.",correct:!1},{text:"Aumentar el número de hijos varones disponibles para la guerra.",correct:!1},{text:"Permitir que las mujeres elijan libremente a sus parejas basándose en el amor romántico.",correct:!1}]},{id:22,text:'¿A qué se refiere el término "currículo oculto" cultural mencionado en el contexto del consumo mediático?',sorted:!1,options:[{text:"A la transmisión implícita de normas y valores sobre sexualidad, éxito o amistad a través de series y redes sociales.",correct:!0},{text:"A los planes de estudio secretos que las empresas tecnológicas imponen en las escuelas privadas.",correct:!1},{text:"A la formación técnica que los niños adquieren para hackear sistemas de control parental.",correct:!1},{text:"Al conjunto de leyes de protección de datos que los menores desconocen.",correct:!1}]},{id:23,text:'En la España actual, ¿qué implica el modelo de "corresponsabilidad educativa"?',sorted:!1,options:[{text:"La colaboración activa entre familias y escuelas en proyectos pedagógicos para una formación integral del alumnado.",correct:!0},{text:"Que los profesores deben hacerse cargo de la alimentación y salud física de los estudiantes en horario extraescolar.",correct:!1},{text:"La obligación de que los padres impartan el 50% de las clases de matemáticas en el aula.",correct:!1},{text:"El pago compartido de las infraestructuras escolares entre el Estado y las asociaciones de padres.",correct:!1}]},{id:24,text:'¿Cuál es una característica de la "familia trasnacional" en el contexto migratorio español?',sorted:!1,options:[{text:"El mantenimiento de vínculos económicos, afectivos y de cuidado a distancia entre miembros que residen en distintos países.",correct:!0},{text:"La prohibición de que los miembros de la familia tengan más de una nacionalidad legal.",correct:!1},{text:"La obligación de viajar al país de origen al menos una vez al mes.",correct:!1},{text:"Hogares formados únicamente por diplomáticos y trabajadores de organizaciones internacionales.",correct:!1}]},{id:25,text:"¿Qué demostraron los estudios sociológicos sobre la distribución desigual del tiempo parental en América Latina?",sorted:!1,options:[{text:"Que influye desde edades tempranas en el desarrollo de habilidades cognitivas y emocionales, perpetuando la desigualdad social.",correct:!0},{text:"Que los padres en contextos de pobreza dedican más tiempo al juego que los padres de clase alta.",correct:!1},{text:"Que el tiempo dedicado a la televisión no tiene impacto si la familia está físicamente presente.",correct:!1},{text:"Que las madres solteras tienen más tiempo disponible para la supervisión escolar en comparación con familias nucleares.",correct:!1}]},{id:26,text:'En el siglo XXI, ¿cuál se considera la función educativa "de primer orden" para las familias ante la digitalización?',sorted:!1,options:[{text:"La mediación parental activa, informada y dialogante en el uso de dispositivos y plataformas digitales.",correct:!0},{text:"La prohibición total de pantallas hasta que el menor alcance la mayoría de edad.",correct:!1},{text:"La contratación de expertos externos para que vigilen el historial de navegación de los hijos.",correct:!1},{text:"Sustituir los libros de texto físicos por aplicaciones móviles diseñadas por los padres.",correct:!1}]},{id:27,text:'¿Qué aspecto de la socialización familiar se describe como "tamiz"?',sorted:!1,options:[{text:"La capacidad de la familia para filtrar el orden social y transmitírselo al individuo como algo absoluto.",correct:!0},{text:"El sistema de castigos que se utiliza para corregir conductas antisociales.",correct:!1},{text:"La selección biológica que ocurre mediante el matrimonio exogámico.",correct:!1},{text:"El proceso por el cual el Estado decide qué familias pueden adoptar niños.",correct:!1}]}],o=[{id:1,text:'¿Cuál de las siguientes características define mejor la "durabilidad" como propiedad de una institución?',sorted:!1,options:[{text:"La permanencia de la estructura física de los centros educativos a lo largo de las décadas.",correct:!1},{text:"La existencia prolongada de normas y prácticas que trascienden la vida de sus integrantes.",correct:!0},{text:"La obligatoriedad legal que impide la disolución de una organización estatal.",correct:!1},{text:"La capacidad de una norma para ser aplicada sin cambios durante un ciclo escolar completo.",correct:!1}]},{id:2,text:'En el marco de las instituciones educativas, ¿qué distingue fundamentalmente a una institución "no formal" de una "informal"?',sorted:!1,options:[{text:"La institución no formal carece de objetivos educativos claros, mientras que la informal sí los tiene.",correct:!1},{text:"La institución no formal está estructurada y persigue fines específicos fuera del sistema oficial, mientras que la informal se basa en prácticas cotidianas no escritas.",correct:!0},{text:"La institución informal está regulada por el Estado, mientras que la no formal es siempre privada.",correct:!1},{text:"No existe distinción real, ya que ambas operan fuera del marco de la educación obligatoria.",correct:!1}]},{id:3,text:'Según Douglas North y el Nuevo Institucionalismo Económico, ¿por qué los agentes sociales aceptan las "reglas del juego" de las instituciones?',sorted:!1,options:[{text:"Porque las instituciones eliminan totalmente la posibilidad de fraude en las interacciones.",correct:!1},{text:"Debido a que proporcionan estabilidad y reducen los costos de transacción generados por la incertidumbre.",correct:!0},{text:"Únicamente por el temor a las sanciones legales impuestas por el pilar regulativo.",correct:!1},{text:"Porque las instituciones siempre garantizan la rentabilidad económica de todas las acciones individuales.",correct:!1}]},{id:4,text:'El concepto de "mito racionalizado" en el neoinstitucionalismo sociológico sugiere que las escuelas a veces adoptan innovaciones pedagógicas para:',sorted:!1,options:[{text:"Maximizar objetivamente el rendimiento académico medido en pruebas estandarizadas.",correct:!1},{text:"Obtener legitimidad social y prestigio al alinearse con tendencias globales, independientemente de su eficacia probada.",correct:!0},{text:"Reducir los costos operativos de la gestión administrativa del centro.",correct:!1},{text:"Cumplir con las demandas biológicas de aprendizaje de los estudiantes.",correct:!1}]},{id:5,text:'De acuerdo con Scott (1995), ¿qué pilar institucional se manifiesta cuando un docente actúa basándose en su "ética profesional" y sentido de deber moral?',sorted:!1,options:[{text:"Pilar regulativo.",correct:!1},{text:"Pilar normativo.",correct:!0},{text:"Pilar cognitivo.",correct:!1},{text:"Pilar isomórfico.",correct:!1}]},{id:6,text:"¿A qué mecanismo de isomorfismo institucional se refiere la tendencia de los centros educativos a copiar modelos de éxito de otros países para evitar la incertidumbre?",sorted:!1,options:[{text:"Isomorfismo coercitivo.",correct:!1},{text:"Isomorfismo normativo.",correct:!1},{text:"Isomorfismo mimético.",correct:!0},{text:"Isomorfismo burocrático.",correct:!1}]},{id:7,text:'En la crítica de la "escuela como fábrica" de Bowles y Gintis, ¿qué elemento se prioriza en detrimento de los objetivos pedagógicos?',sorted:!1,options:[{text:"La creatividad y la autonomía del estudiante.",correct:!1},{text:"El control, la homogeneidad y la estandarización de procesos.",correct:!0},{text:"La diversidad cultural y la inclusión personalizada.",correct:!1},{text:"La gestión democrática de los centros por parte de las familias.",correct:!1}]},{id:8,text:"En la sociedad del conocimiento, ¿cuál es el cambio fundamental en la misión de la escuela?",sorted:!1,options:[{text:"Asegurar que los estudiantes memoricen la mayor cantidad de datos posible ante la volatilidad de internet.",correct:!1},{text:"Pasar de la simple transmisión de contenidos a formar personas con pensamiento crítico y capacidad de aprendizaje colaborativo.",correct:!0},{text:"Sustituir totalmente la figura del profesor por sistemas de inteligencia artificial.",correct:!1},{text:"Centrarse exclusivamente en las competencias técnicas de programación informática.",correct:!1}]},{id:9,text:"¿Cuál es la raíz histórica del énfasis en la descentralización del sistema educativo estadounidense?",sorted:!1,options:[{text:"Una decisión reciente de la OCDE para fomentar la competitividad entre estados.",correct:!1},{text:"El miedo herencial al poder centralizado tras la experiencia colonial británica.",correct:!0},{text:"La imposibilidad geográfica de conectar las escuelas de la costa este con la costa oeste.",correct:!1},{text:"La influencia de las filosofías orientales que valoran la autonomía individual.",correct:!1}]},{id:10,text:"¿Cómo influye el confucianismo en el sistema educativo de Corea del Sur?",sorted:!1,options:[{text:"Fomentando la libre elección de asignaturas y la relajación de la disciplina escolar.",correct:!1},{text:"A través de la valoración del esfuerzo intelectual como deber hacia la familia y vía de movilidad social.",correct:!0},{text:"Promoviendo que el Estado no intervenga en los asuntos educativos de las familias.",correct:!1},{text:"Eliminando la importancia de los exámenes finales para evitar el estrés.",correct:!1}]},{id:11,text:"¿Cuál es un pilar fundamental que explica por qué Finlandia prescinde de inspecciones y exámenes estandarizados masivos?",sorted:!1,options:[{text:"La falta de presupuesto público para contratar inspectores.",correct:!1},{text:"Una profunda confianza social en la formación y profesionalidad de sus docentes.",correct:!0},{text:"El desinterés de la sociedad finlandesa por los resultados de aprendizaje.",correct:!1},{text:"La prohibición constitucional de evaluar a los menores de edad.",correct:!1}]},{id:12,text:"¿Qué contradicción se señala a menudo respecto al modelo meritocrático en el sistema estadounidense?",sorted:!1,options:[{text:"Que las escuelas son demasiado homogéneas y no permiten destacar al talento individual.",correct:!1},{text:"Que la financiación basada en impuestos locales perpetúa las desigualdades de origen, cuestionando el mito de la igualdad de oportunidades.",correct:!0},{text:"Que el gobierno federal impone un currículo único que anula la libertad de elección.",correct:!1},{text:"Que no existen universidades de prestigio para aquellos que se esfuerzan.",correct:!1}]},{id:13,text:'¿cuál es el peligro de aplicar funciones explícitas innovadoras como la "alfabetización digital" de forma meramente ritual?',sorted:!1,options:[{text:"Que los estudiantes aprendan demasiada informática y descuiden las humanidades.",correct:!1},{text:'Que se conviertan en un "escaparate racional" para obtener legitimidad sin resolver los problemas reales del entorno.',correct:!0},{text:"Que el Estado retire la financiación a las escuelas que no usen libros de texto en papel.",correct:!1},{text:"Que se elimine la brecha digital de forma demasiado rápida.",correct:!1}]},{id:14,text:'En el contexto educativo, ¿qué representa una "función implícita" de la institución?',sorted:!1,options:[{text:"Los objetivos curriculares de matemáticas y lengua aprobados por el Ministerio.",correct:!1},{text:'La transmisión de valores y estructuras de poder a través de rutinas y el "clima" escolar.',correct:!0},{text:"Los cursos de formación extracurricular que se pagan aparte.",correct:!1},{text:"La obtención de un título oficial al finalizar los estudios.",correct:!1}]},{id:15,text:'¿Qué pilar institucional de Scott se ve reforzado por la creencia compartida de que "sin título universitario no hay futuro"?',sorted:!1,options:[{text:"Pilar cognitivo.",correct:!0},{text:"Pilar coercitivo.",correct:!1},{text:"Pilar arquitectónico.",correct:!1},{text:"Pilar de isomorfismo.",correct:!1}]},{id:16,text:"El sistema educativo de Finlandia se diferencia del de Corea del Sur principalmente en que el primero:",sorted:!1,options:[{text:"Tiene una mayor centralización estatal del currículo.",correct:!1},{text:"Prioriza el bienestar integral y la cooperación sobre la competitividad extrema.",correct:!0},{text:"Cobra tasas elevadas para garantizar la calidad de sus servicios.",correct:!1},{text:"Fomenta jornadas escolares de más de doce horas diarias.",correct:!1}]},{id:17,text:'Las instituciones educativas son "endógenas" a la sociedad porque:',sorted:!1,options:[{text:"Son impuestas por organismos internacionales ajenos a la cultura local.",correct:!1},{text:"Nacen de las necesidades, valores y procesos históricos de la propia sociedad en la que operan.",correct:!0},{text:"Solo pueden ser gestionadas por personas nacidas en el mismo país.",correct:!1},{text:"Funcionan de manera totalmente independiente a los cambios tecnológicos.",correct:!1}]},{id:18,text:'¿Qué autor es asociado con la visión de las instituciones como mecanismos para reducir la incertidumbre y facilitar la cooperación mediante "reglas del juego"?',sorted:!1,options:[{text:"Douglass North.",correct:!0},{text:"A. S. Neill.",correct:!1},{text:"Francesco Tonucci.",correct:!1},{text:"Max Weber.",correct:!1}]},{id:19,text:'¿Cuál es un ejemplo de "institución informal" dentro del contexto educativo?',sorted:!1,options:[{text:"El Reglamento de Régimen Interno de un instituto.",correct:!1},{text:"La valoración social que se otorga a determinadas carreras universitarias sobre otras.",correct:!0},{text:"Un curso de alfabetización digital para adultos organizado por una asociación.",correct:!1},{text:"La ley estatal que obliga a la escolarización hasta los 16 años.",correct:!1}]},{id:20,text:"El sistema educativo de Corea del Sur prioriza la cohesión social y el bienestar del grupo sobre las aspiraciones individuales. ¿Qué valor cultural sustenta esta visión?",sorted:!1,options:[{text:"El individualismo liberal.",correct:!1},{text:"El colectivismo de raíz confuciana.",correct:!0},{text:"La autonomía del autogobierno local.",correct:!1},{text:"La desconfianza hacia la intervención del Estado.",correct:!1}]},{id:21,text:'En el marco del neoinstitucionalismo sociológico, ¿qué significa actuar bajo la "lógica de lo apropiado"?',sorted:!1,options:[{text:"Tomar decisiones basadas exclusivamente en el cálculo racional de beneficios económicos.",correct:!1},{text:'Comportarse según las normas, valores y expectativas que se asumen como "naturales" o correctas en un contexto dado.',correct:!0},{text:"Seguir únicamente las leyes escritas para evitar sanciones penales.",correct:!1},{text:"Innovar constantemente para romper con todas las tradiciones institucionales.",correct:!1}]},{id:22,text:'¿Qué aspecto de la escuela es comparado con una "fábrica" debido al uso de exámenes nacionales y rankings tipo PISA?',sorted:!1,options:[{text:"La personalización del aprendizaje según el talento de cada niño.",correct:!1},{text:"La tendencia a medir el éxito educativo mediante cifras y estadísticas de productividad.",correct:!0},{text:"La libertad absoluta de los docentes para crear sus propios materiales.",correct:!1},{text:"El fomento del pensamiento divergente y la crítica social.",correct:!1}]},{id:23,text:'¿cuál es la implicación de que la institución educativa sea un escenario de "construcción de legitimidad cognitiva"?',sorted:!1,options:[{text:"Que las personas aprenden a cuestionar todas las verdades impuestas por el Estado.",correct:!1},{text:'Que los individuos terminan asumiendo ciertas rutinas y creencias escolares como la forma "normal" de organizar la vida.',correct:!0},{text:"Que la educación solo sirve para transmitir datos técnicos de difícil comprensión.",correct:!1},{text:"Que el cerebro de los estudiantes se vuelve más resistente a la publicidad.",correct:!1}]},{id:24,text:'¿Qué modelo educativo internacional se describe como basado en la "equidad" y la provisión gratuita de servicios de apoyo como salud y alimentación?',sorted:!1,options:[{text:"El sistema estadounidense.",correct:!1},{text:"El sistema surcoreano.",correct:!1},{text:"El sistema finlandés.",correct:!0},{text:"El sistema anglosajón tradicional.",correct:!1}]},{id:25,text:'¿Por qué los sistemas educativos no pueden "copiarse" de un país a otro de manera acrítica?',sorted:!1,options:[{text:"Porque las leyes de propiedad intelectual prohíben plagiar modelos escolares.",correct:!1},{text:"Porque cada sistema es una expresión auténtica de los valores, historia y aspiraciones de su propia sociedad.",correct:!0},{text:"Porque los idiomas diferentes impiden la traducción de los materiales pedagógicos.",correct:!1},{text:"Porque todos los países tienen ya el mejor sistema posible para sus ciudadanos.",correct:!1}]},{id:26,text:'En la sociedad del conocimiento, ¿cuál es el papel del "aprendizaje a lo largo de toda la vida"?',sorted:!1,options:[{text:"Es una opción voluntaria para personas que tienen mucho tiempo libre.",correct:!1},{text:"Se convierte en una necesidad central debido a la velocidad vertiginosa con la que se genera y comparte el saber.",correct:!0},{text:"Es una estrategia de las universidades para cobrar más matrículas durante más años.",correct:!1},{text:"Sirve para sustituir la educación obligatoria de la infancia.",correct:!1}]},{id:27,text:"¿Qué ejemplo de institución educativa alternativa se menciona como modelo antiautoritario basado en la libertad?",sorted:!1,options:[{text:"Mäntykangas en Oulu.",correct:!1},{text:"Summerhill School de A. S. Neill.",correct:!0},{text:"Daewon Foreign Language High School.",correct:!1},{text:"Highland Park ISD en Texas.",correct:!1}]}],t=[{id:1,text:'¿A qué se refieren Friedmann (1966) y Porcher (1976) al utilizar el concepto de "escuela paralela"?',sorted:!1,options:[{text:"A los centros de educación no formal que ofrecen formación técnica fuera del currículo oficial.",correct:!1},{text:"Al conjunto de vías mediáticas que transmiten información y cultura al margen de la institución escolar.",correct:!0},{text:'A la educación en casa o "homeschooling" mediada por plataformas digitales y tutores privados.',correct:!1},{text:"A las actividades extraescolares organizadas por la familia para complementar la formación académica.",correct:!1}]},{id:2,text:"En el marco de las etapas de socialización, ¿dónde se ubican principalmente los medios de comunicación como agentes?",sorted:!1,options:[{text:"Socialización primaria.",correct:!1},{text:"Socialización secundaria.",correct:!0},{text:"Socialización terciaria.",correct:!1},{text:"Socialización cuaternaria.",correct:!1}]},{id:3,text:"¿Cuál fue el impacto decisivo de la prensa decimonónica en España tras la Guerra de la Independencia?",sorted:!1,options:[{text:"La creación de la primera agencia de noticias estatal para controlar el flujo informativo.",correct:!1},{text:"El reconocimiento de la libertad de imprenta en 1810 por las Cortes de Cádiz.",correct:!0},{text:"La obligatoriedad de incluir secciones educativas en todos los diarios nacionales.",correct:!1},{text:"La prohibición de las novelas por entregas para priorizar la información política.",correct:!1}]},{id:4,text:"Según Pindado (2006), ¿cómo utilizan los adolescentes los contenidos mediáticos en relación con su identidad?",sorted:!1,options:[{text:"Como un sustituto de la interacción real para evitar el rechazo social.",correct:!1},{text:'Como una "caja de herramientas" para negociar y elaborar su propia identidad.',correct:!0},{text:"Como un manual de instrucciones rígido que deben seguir para ser aceptados.",correct:!1},{text:"Como una fuente de desinformación que deben rechazar para mantener su autenticidad.",correct:!1}]},{id:5,text:"¿Qué fenómeno caracterizó la función socializadora del cine entre 1910 y 1920?",sorted:!1,options:[{text:"El predominio del cine documental sobre la ficción narrativa.",correct:!1},{text:'La consolidación del "star system" como generador de iconos culturales y modelos estéticos.',correct:!0},{text:"La desaparición de los estereotipos nacionales en favor de una identidad puramente europea.",correct:!1},{text:"La prohibición de que las actrices mostraran comportamientos que desafiaran los códigos tradicionales.",correct:!1}]},{id:6,text:"¿Cuál fue el impacto social del Neorrealismo italiano tras la Segunda Guerra Mundial?",sorted:!1,options:[{text:"Promovió el escapismo a través de comedias ligeras para olvidar el conflicto.",correct:!1},{text:"Funcionó como un documento social que educaba al público sobre la crisis y las condiciones reales del país.",correct:!0},{text:"Estableció las bases del cine de terror moderno basado en los traumas de la guerra.",correct:!1},{text:"Reforzó el sistema de estudios de Hollywood mediante coproducciones masivas.",correct:!1}]},{id:7,text:"En el contexto de la Segunda Guerra Mundial, ¿cómo utilizó Joseph Goebbels la radio en la invasión de Francia?",sorted:!1,options:[{text:"Emitiendo música clásica para calmar a las tropas francesas.",correct:!1},{text:'Creando una emisora falsa denominada "Radio Humanité" para difundir rumores y pánico.',correct:!0},{text:"Interfiriendo las señales de la BBC para que no llegaran a los hogares franceses.",correct:!1},{text:"Difundiendo discursos de Hitler traducidos al francés para convencer a la población.",correct:!1}]},{id:8,text:'¿Qué papel desempeñaron programas como el "Consultorio de Elena Francis" en la España de posguerra?',sorted:!1,options:[{text:"Fomentaron la independencia económica de la mujer a través de consejos laborales.",correct:!1},{text:"Actuaron como vehículos para la difusión del nacionalcatolicismo y modelos de feminidad tradicionales.",correct:!0},{text:"Eran espacios de debate político clandestino disfrazados de programas de entretenimiento.",correct:!1},{text:"Promovieron la modernización estética de los hogares españoles siguiendo el modelo americano.",correct:!1}]},{id:9,text:"Entre 1950 y 2000, ¿cuál fue el principal cambio que introdujo la televisión en la dinámica familiar?",sorted:!1,options:[{text:"El aislamiento de los miembros de la familia en habitaciones separadas.",correct:!1},{text:"El reacomodo de la vida doméstica y sus ritmos (cenas, horarios) en torno a la programación.",correct:!0},{text:"La desaparición total del interés por los eventos comunitarios presenciales.",correct:!1},{text:"La sustitución de la publicidad por contenidos puramente educativos de carácter estatal.",correct:!1}]},{id:10,text:"¿Qué diferencia fundamental introdujo Internet (1990-2010) respecto a la radio y la televisión tradicionales?",sorted:!1,options:[{text:"La creación de una única audiencia nacional cohesionada por contenidos comunes.",correct:!1},{text:"La fragmentación y personalización del consumo mediático (dieta informativa a la carta).",correct:!0},{text:"La eliminación de los filtros algorítmicos para asegurar una información neutral.",correct:!1},{text:"La obligatoriedad de registrarse en plataformas estatales para acceder a la red.",correct:!1}]},{id:11,text:"¿Cómo afectó el lanzamiento de Facebook en 2004 a los mecanismos de socialización?",sorted:!1,options:[{text:"Restableció las jerarquías verticales entre emisores profesionales y receptores pasivos.",correct:!1},{text:"Introdujo dinámicas de comunicación horizontal y validación social basadas en métricas cuantificables.",correct:!0},{text:"Eliminó la necesidad de construir una identidad pública para centrarse en la privacidad.",correct:!1},{text:"Limitó la socialización a grupos de edad avanzada para proteger a los menores.",correct:!1}]},{id:12,text:'¿Qué peligro para la deliberación democrática representan las llamadas "burbujas algorítmicas"?',sorted:!1,options:[{text:"La sobreabundancia de opiniones divergentes que confunden al ciudadano.",correct:!1},{text:"El refuerzo de sesgos de confirmación al exponernos solo a contenidos que coinciden con nuestros gustos.",correct:!0},{text:"La eliminación automática de cualquier contenido con carga política o social.",correct:!1},{text:"El aumento del coste de acceso a información de calidad para los jóvenes.",correct:!1}]},{id:13,text:"Según el informe de Save the Children (2024), ¿qué porcentaje de niños y adolescentes españoles no sabe identificar noticias falsas?",sorted:!1,options:[{text:"25%",correct:!1},{text:"51%",correct:!0},{text:"75%",correct:!1},{text:"10%",correct:!1}]},{id:14,text:'¿Qué caracteriza a las "relaciones parasociales" que los adolescentes establecen con los influencers?',sorted:!1,options:[{text:"Son vínculos bidireccionales basados en el conocimiento mutuo profundo.",correct:!1},{text:"Son vínculos emocionales unidireccionales donde la audiencia siente una familiaridad irreal con el creador.",correct:!0},{text:"Son contratos formales de colaboración para la creación de contenido conjunto.",correct:!1},{text:'Son interacciones basadas exclusivamente en el odio o la crítica destructiva ("hater").',correct:!1}]},{id:15,text:"¿Cuál es la relación entre el uso de redes sociales y los trastornos de la conducta alimentaria (TCA)?",sorted:!1,options:[{text:"Las redes sociales actúan como filtro protector al denunciar automáticamente contenidos de extrema delgadez.",correct:!1},{text:"Fomentan la comparación constante entre iguales y el uso de hashtags específicos que promueven conductas de riesgo.",correct:!0},{text:"Han eliminado la preocupación por el peso al priorizar la diversidad corporal en todos los algoritmos.",correct:!1},{text:"No existe una correlación demostrada entre el consumo visual digital y la salud mental adolescente.",correct:!1}]},{id:16,text:'El término "nomofobia" hace referencia a:',sorted:!1,options:[{text:"El rechazo sistemático a las nuevas tecnologías por parte de los docentes.",correct:!1},{text:"El miedo irracional a estar sin el teléfono móvil o desconectado.",correct:!0},{text:"La incapacidad de distinguir entre la realidad física y la realidad virtual.",correct:!1},{text:"La fobia a ser grabado o fotografiado sin consentimiento en espacios públicos.",correct:!1}]},{id:17,text:'¿Por qué el diseño de las plataformas digitales se considera en ocasiones "adictivo"?',sorted:!1,options:[{text:"Porque el coste de suscripción es tan bajo que es imposible dejar de pagarlo.",correct:!1},{text:"Porque utiliza mecánicas de recompensa intermitente y notificaciones estratégicas para maximizar la permanencia.",correct:!0},{text:"Porque el contenido educativo es tan complejo que requiere horas de estudio continuo.",correct:!1},{text:"Porque los gobiernos obligan a los ciudadanos a pasar un tiempo mínimo en redes sociales.",correct:!1}]},{id:18,text:'¿Qué implicación ética tiene la "monetización de la infancia" en plataformas como YouTube?',sorted:!1,options:[{text:"Garantiza que los menores ahorren dinero para su futura educación universitaria.",correct:!1},{text:"Convierte a niños en celebridades cuya actividad se mercantiliza, exponiéndolos a presiones de mercado precoces.",correct:!0},{text:"Permite que los niños aprendan nociones avanzadas de economía y gestión de empresas.",correct:!1},{text:"Asegura que el contenido sea siempre de alta calidad pedagógica para otros niños.",correct:!1}]},{id:19,text:'¿Cómo afectó el fallo del caso "Paramount vs. Estados Unidos" (1948) a la industria cinematográfica?',sorted:!1,options:[{text:"Obligó a los estudios a producir únicamente películas en color.",correct:!1},{text:"Forzó a los grandes estudios a desprenderse de sus salas de cine, terminando con su control vertical.",correct:!0},{text:"Prohibió la entrada de menores de edad en las salas de cine de todo el país.",correct:!1},{text:"Estableció que el gobierno debía financiar todas las producciones independientes.",correct:!1}]},{id:20,text:'La "Nouvelle Vague" francesa es citada como ejemplo de cómo el cine puede:',sorted:!1,options:[{text:"Sustituir a los libros de texto en las escuelas de primaria.",correct:!1},{text:"Renovar el lenguaje visual e influir incluso en las formas de vestir y hablar de la juventud.",correct:!0},{text:"Crear efectos especiales digitales que revolucionaron la industria del entretenimiento.",correct:!1},{text:"Alinear la opinión pública francesa con las políticas de la OTAN.",correct:!1}]},{id:21,text:'¿Qué función cumple el algoritmo "For You Page" de TikTok en el proceso de socialización actual?',sorted:!1,options:[{text:"Obliga a los usuarios a ver contenidos aleatorios para fomentar la diversidad cultural.",correct:!1},{text:"Crea flujos de contenido individualizados que mantienen al usuario enganchado mediante el análisis de señales sutiles.",correct:!0},{text:"Filtra automáticamente cualquier contenido que no sea estrictamente educativo o científico.",correct:!1},{text:"Conecta a los adolescentes únicamente con personas de su entorno geográfico inmediato.",correct:!1}]},{id:22,text:'¿Cuál es un rasgo distintivo del discurso de la "escuela paralela" frente al de la escuela tradicional?',sorted:!1,options:[{text:"Su carácter abstracto y altamente teórico.",correct:!1},{text:"Ofrece contenidos más visuales, directos, amenos y menos complejos estructuralmente.",correct:!0},{text:"La exigencia de una evaluación formal para pasar al siguiente nivel de consumo.",correct:!1},{text:"Su enfoque exclusivo en la historia antigua y las lenguas clásicas.",correct:!1}]},{id:23,text:'¿Qué impacto tiene el "binge-watching" en la sincronía colectiva de la sociedad?',sorted:!1,options:[{text:"Aumenta la cohesión social al asegurar que todos vean lo mismo al mismo tiempo.",correct:!1},{text:"Desvanece la conversación social compartida al consumir cada espectador a su propio ritmo.",correct:!0},{text:"Mejora la calidad del sueño al permitir ver temporadas completas durante el día.",correct:!1},{text:"Fomenta la paciencia de los adolescentes al obligarles a esperar estrenos anuales.",correct:!1}]},{id:24,text:"En la era de la televisión (1950-2000), ¿qué cambio fundamental se produjo en el relato publicitario?",sorted:!1,options:[{text:"Se centró exclusivamente en enumerar las características técnicas de los productos.",correct:!1},{text:"Dejó de describir prestaciones para escenificar estilos de vida e identidades aspiracionales.",correct:!0},{text:"Se prohibió el uso de música y celebridades para no distraer al consumidor.",correct:!1},{text:"La publicidad desapareció de la programación infantil por motivos éticos.",correct:!1}]},{id:25,text:"¿Cuál de las siguientes es una función socializadora específica de los medios de comunicación?",sorted:!1,options:[{text:"La imposición de sanciones legales a quienes no consuman cultura nacional.",correct:!1},{text:"La transmisión de valores, normas y patrones culturales de manera constante.",correct:!0},{text:"La sustitución de la familia como agente único de socialización primaria.",correct:!1},{text:"La obligatoriedad de la alfabetización mediática para obtener la ciudadanía.",correct:!1}]},{id:26,text:"¿Qué efecto tiene la microsegmentación mediática en la identidad de los adolescentes actuales?",sorted:!1,options:[{text:"Genera identidades homogéneas basadas en un solo canal de televisión.",correct:!1},{text:"Produce identidades mediáticas profundamente individualizadas que apenas se superponen con las de sus iguales.",correct:!0},{text:"Fortalece la identidad nacional al priorizar contenidos locales sobre los globales.",correct:!1},{text:"Elimina la necesidad de validación externa al centrarse en el autoconocimiento.",correct:!1}]}];export{e as EESF_UD1_QUESTIONS,a as EESF_UD2_QUESTIONS,o as EESF_UD3_QUESTIONS,t as EESF_UD4_QUESTIONS};